import json

with open('mcp-agent-ml-research-read_registry-1779296653687.txt', 'r') as f:
    data = json.load(f)

registry = json.loads(data['result'])

# Search keywords
keywords = ['filter', 'downstream', 'lora', 'finetune', 'fine_tune', 'fine-tune', 'binary', 'graduated', 'no_filter', 'no-filter', 'expanded_downstream', 'section5', 'section_5']

# Find matching experiments
matches = []
for exp_id, exp_data in registry.items():
    exp_id_lower = exp_id.lower()
    matched = False
    for kw in keywords:
        if kw in exp_id_lower:
            matched = True
            break
    if not matched:
        # Also search in description, notes, conclusion fields
        for field in ['description', 'notes', 'conclusion', 'config']:
            val = exp_data.get(field, '')
            if isinstance(val, str):
                val_lower = val.lower()
                for kw in keywords:
                    if kw in val_lower:
                        matched = True
                        break
            elif isinstance(val, dict):
                val_str = json.dumps(val).lower()
                for kw in keywords:
                    if kw in val_str:
                        matched = True
                        break
            if matched:
                break
    if matched:
        matches.append((exp_id, exp_data))

print(f'Total experiments in registry: {len(registry)}')
print(f'Matching experiments: {len(matches)}')
print('='*120)

for exp_id, exp_data in sorted(matches, key=lambda x: x[0]):
    print(f'\n{\"=\"*120}')
    print(f'exp_id: {exp_id}')
    print(json.dumps(exp_data, indent=2, ensure_ascii=False))
